import pytest

def clamp(x, lo, hi):
    if lo > hi:
        raise ValueError('lo > hi')
    return max(lo, min(x, hi))

# Test cases
test_data = [
    (5, 1, 10, 5),       # Normal case: x within bounds
    (-3, -10, 0, -3),    # Lower bound case: x is less than lower bound
    (15, 10, 20, 15),    # Upper bound case: x is greater than upper bound
    (8, 10, 9, 9),       # Upper bound case with reversed bounds
    (-5, -3, -7, -3),    # Lower bound case with reversed bounds
    (2, 3, 1, None)      # Error case: lo > hi
]

@pytest.mark.parametrize("x, lo, hi, expected", test_data)
def test_clamp(x, lo, hi, expected):
    if expected is None:
        with pytest.raises(ValueError):
            clamp(x, lo, hi)
    else:
        assert clamp(x, lo, hi) == expected
```

